      "evidence": {
        "source": "toy",
        "locator": "body.results.mailparser.checks a4-trace.names, m2-two-subjects.names"
      }
    },
    {
      "claim": "No candidate parses the Appendix A obsolete and commented forms: A.5 (comments in groups), A.6.1 (route, empty list element, spaced dot), A.6.3 (CFWS in address, date and msg-id). postal-mime and mailparser fail the same 7 checks the same way.",
      "status": "verified",
      "evidence": {
        "source": "toy",
        "locator": "body.results"
      }
    },
    {
