    "harness_source": "// Build or depend: run three parsers over RFC 5322 Appendix A and malformed\n// fixtures, and compare with results written by hand from the RFC text.\nimport fs from 'node:fs';\nimport PostalMime from 'postal-mime';\nimport { simpleParser } from 'mailparser';\nimport * as letter from 'letterparser';\n\nconst files = fs.readdirSync('fixtures').filter((f) => f.endsWith('.eml')).sort();\n\n// Expected values, from the RFC prose around each example.\nconst mb = (name, addr) => ({ name, addr });\nconst grp = (group, members) => ({ group, members });\nconst expected = {\n  'a1.2-mailboxes': {\n    from: [mb('Joe Q. Public', 'john.q.public@example.com')],\n    to: [mb('Mary Smith', 'mary@x.test'), mb('', 'jdoe@example.org'), mb('Who?', 'one@y.test')],\n    cc: [mb('', 'boss@nil.test'), mb('Giant; \"Big\" Box', 'sysservices@example.net')],\n  },\n  'a1.3-groups': {\n    to: [grp('A Group', [mb('Ed Jones', 'c@a.test'), mb('', 'joe@where.test'), mb('John', 'jdoe@one.test')])],\n    cc: [grp('Undisclosed recipients', [])],\n  },\n  'a2-3-reply': {\n    messageId: 'abcd.1234@local.machine.test',\n    inReplyTo: ['3456@example.net'],\n    references: ['1234@local.machine.example', '3456@example.net'],\n  },\n  'a3-resent': {\n    names: ['Resent-From', 'Resent-To', 'Resent-Date', 'Resent-Message-ID', 'From', 'To', 'Subject', 'Date', 'Message-ID'],\n  },\n  'a4-trace': {\n    names: ['Received', 'Received', 'From', 'To', 'Subject', 'Date', 'Message-ID'],\n  },\n  'a5-oddities': {\n    from: [mb('Pete', 'pete@silly.test')],\n    to: [grp('A Group', [mb('Chris Jones', 'c@public.example'), mb('', 'joe@example.org'), mb('John', 'jdoe@one.test')])],\n    cc: [grp('Hidden recipients', [])],\n    date: '1969-02-14T03:02:00.000Z',\n    messageId: 'testabcd.1234@silly.test',\n  },\n  'a6.1-obs-address': {\n    from: [mb('Joe Q. Public', 'john.q.public@example.com')],\n    to: [mb('Mary Smith', 'mary@example.net'), mb('', 'jdoe@test.example')],\n  },\n  'a6.2-obs-date': { date: '1997-11-21T09:55:06.000Z' },\n  'a6.3-obs-ws': {\n    from: [mb('John Doe', 'jdoe@machine.example')],\n    to: [mb('Mary Smith', 'mary@example.net')],\n    date: '1997-11-21T15:55:06.000Z',\n    messageId: '1234@local.machine.example',\n  },\n  'm2-two-subjects': { names: ['From', 'Date', 'Subject', 'Subject'] },\n  'm5-feb30': { date: null }, // 3.3: not semantically valid, so no instant\n};\n\nconst ids = (s) => (s == null ? undefined : [...String(s).matchAll(/<([^>]*)>/g)].map((m) => m[1]));\nconst addr = (a) =>\n  a.group !== undefined\n    ? grp((a.name ?? '').trim(), a.group.map(addr))\n    : mb((a.name ?? '').trim(), a.address ?? '');\nconst list = (v) => (v == null ? undefined : (Array.isArray(v) ? v : [v]).map(addr));\nconst iso = (d) => {\n  if (d == null || d === '') return null;\n  const t = new Date(d);\n  return Number.isNaN(t.getTime()) ? null : t.toISOString();\n};\n\n// Each adapter maps a parser's result onto one shape for comparison only.\nconst parsers = {\n  'postal-mime': async (raw) => {\n    const p = await PostalMime.parse(raw);\n    return {\n      names: p.headers.map((h) => h.originalKey ?? h.key),\n      rawLines: Array.isArray(p.headerLines),\n      from: list(p.from), to: list(p.to), cc: list(p.cc),\n      date: iso(p.date),\n      messageId: ids(p.messageId)?.[0],\n      inReplyTo: ids(p.inReplyTo), references: ids(p.references),\n    };\n  },\n  mailparser: async (raw) => {\n    const m = await simpleParser(raw);\n    return {\n      names: m.headerLines.map((h) => h.line.slice(0, h.line.indexOf(':')).trim()),\n      rawLines: true,\n      from: list(m.from?.value), to: list(m.to?.value), cc: list(m.cc?.value),\n      date: iso(m.date),\n      messageId: ids(m.messageId)?.[0],\n      inReplyTo: ids(m.inReplyTo),\n      references: m.references == null ? undefined : (Array.isArray(m.references) ? m.references : [m.references]).flatMap(ids),\n    };\n  },\n  letterparser: async (raw) => {\n    const text = raw.toString('latin1');\n    const h = letter.parse(text).headers;\n    const x = letter.extract(text);\n    return {\n      names: Object.keys(h),\n      rawLines: false,\n      from: list(x.from), to: list(x.to), cc: list(x.cc),\n      date: iso(x.date),\n      messageId: ids(h['Message-Id'] ?? h['Message-ID'])?.[0],\n      inReplyTo: ids(h['In-Reply-To']), references: ids(h['References']),\n    };\n  },\n};\n\nconst results = {};\nfor (const [name, run] of Object.entries(parsers)) {\n  const r = { threw: [], checks: {}, pass: 0, fail: 0 };\n  for (const f of files) {\n    const key = f.replace(/\\.eml$/, '');\n    let got;\n    try { got = await run(fs.readFileSync(`fixtures/${f}`)); }\n    catch (e) { r.threw.push(`${key}: ${String(e.message).slice(0, 80)}`); continue; }\n    for (const [field, want] of Object.entries(expected[key] ?? {})) {\n      const ok = JSON.stringify(got[field] ?? null) === JSON.stringify(want);\n      r.checks[`${key}.${field}`] = ok ? 'pass' : { want, got: got[field] ?? null };\n      ok ? r.pass++ : r.fail++;\n    }\n  }\n  results[name] = r;\n}\nfs.writeFileSync('results.json', JSON.stringify(results, null, 2));\nfor (const [n, r] of Object.entries(results)) {\n  console.log(`${n}: ${r.pass} pass, ${r.fail} fail, threw on ${r.threw.length}`);\n  for (const [k, v] of Object.entries(r.checks)) if (v !== 'pass') console.log(`  FAIL ${k}: want ${JSON.stringify(v.want)} got ${JSON.stringify(v.got)}`);\n  for (const t of r.threw) console.log(`  THREW ${t}`);\n}\n",
